  ],
  "blocker_attribution": "genuine",
  "verdict_reason": "环境(py2.7 + TF1.12 + T2T1.12)已成功搭好,但仓库 layers/ 缺 __init__.py,T2T 加载 usr_dir 时 ImportError,不改代码就无法注册模型。"
}
